 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            objs.append((color, cells))
    out = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,) and not any((r,c) in cells for _, cells in objs):
                out[r][c] = grid[r][c]
    # Objects move toward the 2-colored boundary (upward), as rigid shapes.
    objs.sort(key=lambda ob: min(r for r,c in ob[1]))
    for color, cells in objs:
        cells = list(cells)
        while min(r for r,c in cells) > 0 and all(out[r-1][c] == 0 for r,c in cells):
            cells = [(r-1,c) for r,c in cells]
        for r,c in cells:
            out[r][c] = color
    return out
"
