{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Identify the fixed 2-colored wall, and let every other connected object
    # fall toward it, preserving the initial lower-first order.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            objects.append((color, cells))
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
    # Process bottommost objects first, as in the demonstration.
    objects.sort(key=lambda obj: max(r for r, c in obj[1]), reverse=True)
    for color, cells in objects:
        while max(r for r, c in cells) + 1 < h and all(out[r + 1][c] == 0 for r, c in cells):
            cells = [(r + 1, c) for r, c in cells]
        for r, c in cells:
            out[r][c] = color
    return out
"
}

