    # Demo shows objects are compressed toward wall, in parallel lines, not
    # allowed to cross; stable order measured perpendicular to wall.
    out = [[0] * w for _ in range(h)]
    for r, c in wall:
        out[r][c] = 2
    groups = {}
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col in (0, 2):
                continue
            groups.setdefault(col, []).append((r, c))
    # Rigid connected same-colored components, each moves independently along
    # the axis toward the wall, processing the closest objects first.
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col in (0, 2) or (r,c) in seen:
                continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==col:
                        seen.add(p); q.append(p)
            objs.append((col,cells))
    def key(o):
        cells=o[1]
        if horizontal:
            return min(c for r,c in cells) if wall[0][1]==0 else -max(c for r,c in cells)
        return min(r for r,c in cells) if wall[0][0]==0 else -max(r for r,c in cells)
    objs.sort(key=key)
    dr,dc=(0,1) if horizontal and wall[0][1]==0 else (0,-1) if horizontal else (1,0) if wall[0][0]==0 else (-1,0)
    for col,cells in objs:
        while True:
            nxt=[(r+dr,c+dc) for r,c in cells]
            if any(r<0 or r>=h or c<0 or c>=w or out[r][c] for r,c in nxt): break
            cells=nxt
        for r,c in cells: out[r][c]=col
    return out
