{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if len({r for r,c in wall}) == 1:
        dr,dc = (-1,0) if wall[0][0] == 0 else (1,0)
    else:
        dr,dc = (0,-1) if wall[0][1] == 0 else (0,1)
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color in (0,2) or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); q.append(p)
            edge = (min(r for r,c in cells) if dr<0 else max(r for r,c in cells)) if dr else (min(c for r,c in cells) if dc<0 else max(c for r,c in cells))
            objects.append((edge,color,cells))
    out=[[0]*w for _ in range(h)]
    for r,c in wall: out[r][c]=2
    objects.sort(key=lambda z:z[0], reverse=(dr<0 or dc<0))
    for _,color,cells in objects:
        while True:
            moved=[(r+dr,c+dc) for r,c in cells]
            if any(r<0 or r>=h or c<0 or c>=w or out[r][c]!=0 for r,c in moved): break
            cells=moved
        for r,c in cells: out[r][c]=color
    return out
"
